<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue';import {useLab} from '../store';import {type Simulation,type Execution,exportText} from '../api';import {usePlayback} from '../animation/usePlayback';import MotionControls from '../components/MotionControls.vue';import SchedulePlayback from '../components/SchedulePlayback.vue';import SqlEditor from '../components/SqlEditor.vue';import ResultTable from '../components/ResultTable.vue';
const scheduleEditor=ref<InstanceType<typeof SqlEditor>>();function highlightLine(line:number|null){const text=lab.workspace?.schedule.split('\n')[(line??1)-1]??'';scheduleEditor.value?.highlight(line===null?null:{start:0,end:0,line,column:1,end_line:line,end_column:text.length+1})}
const props=defineProps<{theme:string}>();const emit=defineEmits<{connect:[]}>();const lab=useLab();const section=ref('model');const mode=ref('raw');const isolation=ref('ru');const result=ref<Simulation>();const index=ref(0);const initial=ref(JSON.stringify(lab.workspace?.initial??{A:300,B:300}));const realSql=ref({A:"START TRANSACTION;\nSELECT * FROM Account WHERE Ano='A';",B:"START TRANSACTION;\nUPDATE Account SET balance=balance+100 WHERE Ano='A';\nCOMMIT;"});const history=ref<{session:string,sql:string,result:Execution,time:string}[]>([]);const historyCount=computed(()=>history.value.length);const historyPlayer=usePlayback(historyCount);const historyIndex=historyPlayer.index;const serverIsolation=ref('REPEATABLE READ');
const examples=[['丢失修改','T1 read A\nT2 read A\nT1 set A A-100\nT1 write A\nT1 commit\nT2 set A A-200\nT2 write A\nT2 commit'],['脏读与级联','T1 write A 200\nT2 read A\nT2 commit\nT1 rollback'],['不可重复读','T1 read A\nT2 write A 500\nT2 commit\nT1 read A\nT1 commit'],['幻读','T1 scan A 0 1000\nT2 insert A2 200\nT2 commit\nT1 scan A 0 1000\nT1 commit'],['死锁（可重复读锁模型）','T1 read A\nT2 read B\nT1 write B 1\nT2 write A 2'],['视图可串行化的盲写','T1 write A 10\nT2 write A 20\nT1 write A 30']];
watch(()=>lab.epoch,()=>{result.value=undefined;historyPlayer.pause()});
watch(()=>[lab.workspace?.schedule,mode.value,isolation.value,initial.value],()=>{lab.touch();result.value=undefined;index.value=0});
async function simulate(){result.value=undefined;await scheduleEditor.value?.source(true);try{const values=JSON.parse(initial.value)as Record<string,number>;if(Object.values(values).some(v=>!Number.isSafeInteger(v)))throw new Error('初始值需要安全范围内的整数');lab.workspace!.initial=values;const r=await lab.run<Simulation>('schedule','simulate',{source:lab.workspace!.schedule,initial:values,mode:mode.value,isolation:isolation.value});if(r){result.value=r;index.value=0;lab.log(`事务模拟：${r.status}`)}}catch(e){lab.fail(e)}}
async function execute(session:'A'|'B',override?:string){const sql=override??realSql.value[session];const r=await lab.run<Execution>(`mysql-${session}`,'execute',{engine:'mysql',session,sql});if(r){history.value.push({session,sql,result:r,time:new Date().toLocaleTimeString()});await nextTick();historyPlayer.seek(history.value.length-1);lab.log(`会话 ${session}：${r.error??r.transaction}`)}}
async function report(){await exportText(`# 事务实验报告\n\n模型：${mode.value} / ${isolation.value}\n\n\`\`\`text\n${lab.workspace?.schedule}\n\`\`\`\n\n\`\`\`json\n${JSON.stringify(result.value,null,2)}\n\`\`\`\n`,'事务实验.md');}
</script>
<template><div class="lab-page"><header class="page-heading"><div><span class="eyebrow">TRANSACTION LAB</span><h1>让并发过程变得可见</h1><p>课本锁模型与 MySQL 真实会话分别运行、分别解释。</p></div><div class="segmented"><button :class="{active:section==='model'}" @click="section='model'">教学模型</button><button :class="{active:section==='real'}" @click="section='real'">MySQL 双会话</button></div></header><template v-if="section==='model'"><div class="transaction-grid"><section class="schedule-input"><div class="toolbar"><select @change="lab.workspace!.schedule=($event.target as HTMLSelectElement).value;lab.touch()"><option value="">调度示例…</option><option v-for="[label,text] in examples" :key="label" :value="text">{{label}}</option></select><button @click="report().catch(lab.fail)" :disabled="!result">报告 ↗</button></div><label>初始数据（JSON）<input v-model="initial" aria-label="事务初始值" @input="lab.touch()"></label><div v-if="lab.workspace" class="schedule-code"><SqlEditor ref="scheduleEditor" id="schedule" v-model="lab.workspace.schedule" language="plaintext" :theme="props.theme" :schema="lab.schema" @update:model-value="lab.touch()"/></div><div class="toolbar"><select v-model="mode"><option value="raw">原始调度（无锁）</option><option value="locks">课本锁控制</option></select><select v-model="isolation"><option value="ru">READ UNCOMMITTED</option><option value="rc">READ COMMITTED</option><option value="rr">REPEATABLE READ</option><option value="serializable">SERIALIZABLE</option></select></div><button class="primary" data-testid="simulate" :disabled="!!lab.jobs.schedule" @click="simulate">▶ 模拟并判定</button><details class="syntax-card"><summary>操作语法</summary><pre>T1 read A\nT1 set A A-100\nT1 write A\nT2 insert A2 200\nT1 scan A 0 1000\nT1 commit\nT2 rollback</pre><p>scan 使用数据项名称前缀和闭区间值范围。write 可显式给值；不写值时使用已读取的同名局部变量。</p></details></section><section class="schedule-output"><template v-if="result"><div class="metrics"><div><small>冲突可串行化</small><strong :class="result.analysis.conflict_serializable?'success':'error'">{{result.analysis.conflict_serializable?'是':'否'}}</strong></div><div><small>视图可串行化</small><strong>{{result.analysis.view_serializable===null?'未完成':result.analysis.view_serializable?'是':'否'}}</strong></div><div><small>可恢复 / 无级联</small><strong>{{result.recoverable?'是':'否'}} / {{result.cascadeless?'是':'否'}}</strong></div></div><SchedulePlayback :result="result" :source="lab.workspace!.schedule" @line="highlightLine"/><div v-for="warning in result.anomalies" :key="warning" class="notice warning">{{warning}}</div><details class="syntax-card"><summary>冲突依据（{{result.analysis.edges.length}}）</summary><p v-for="(edge,i) in result.analysis.edges" :key="i">操作 {{edge.first+1}} → {{edge.second+1}}：{{edge.from}} → {{edge.to}}，{{edge.item}}，{{edge.kind}}</p></details></template><div v-else class="empty large">T₁ ⇄ T₂<p>每一次读、写、等待和提交，都留下可回放的记录。</p></div></section></div></template><template v-else><div class="notice">真实连接需要 MySQL。先在连接设置中创建 Bank 教学沙箱；普通 SELECT 和加锁读遵循服务器的实际实现。<button @click="emit('connect')">连接设置</button></div><div class="toolbar"><select v-model="serverIsolation"><option>READ UNCOMMITTED</option><option>READ COMMITTED</option><option>REPEATABLE READ</option><option>SERIALIZABLE</option></select><button @click="execute('A',`SET SESSION TRANSACTION ISOLATION LEVEL ${serverIsolation}`);execute('B',`SET SESSION TRANSACTION ISOLATION LEVEL ${serverIsolation}`)">设置两个会话隔离级别</button></div><div class="session-grid"><section v-for="session in (['A','B'] as const)" :key="session" class="session"><div class="toolbar"><strong>会话 {{session}}</strong><button class="primary" :disabled="!!lab.jobs[`mysql-${session}`]" @click="execute(session)">▶ 执行脚本</button><button @click="execute(session,'COMMIT')">提交</button><button @click="execute(session,'ROLLBACK')">回滚</button><button @click="lab.cancel(`mysql-${session}`)">取消</button></div><SqlEditor :id="`mysql-${session}`" v-model="realSql[session]" :schema="lab.schema" engine="mysql" :theme="props.theme" @run="execute(session)"/><div v-if="lab.jobs[`mysql-${session}`]" class="notice live-pending">正在等待服务器响应… 可在另一会话中继续操作。</div></section></div><div v-if="history.length" class="history"><h3>真实会话历史 · 点击只回放结果，不重新执行</h3><MotionControls :index="historyIndex" :count="history.length" :progress="historyPlayer.progress.value" :playing="historyPlayer.playing.value" :speed="historyPlayer.speed.value" :label="'真实会话 '+history[historyIndex].session" @seek="historyPlayer.seek($event)" @toggle="historyPlayer.toggle" @speed="historyPlayer.speed.value=$event"/><div class="file-tabs"><button v-for="(h,i) in history" :key="i" :class="{active:i===historyIndex}" @click="historyPlayer.seek(i)">{{h.time}} · {{h.session}}</button></div><pre>{{history[historyIndex].sql}}</pre><div class="notice" :class="{warning:!!history[historyIndex].result.error}">{{history[historyIndex].result.error??history[historyIndex].result.transaction}}</div><ResultTable v-for="(r,i) in history[historyIndex].result.results" :key="i" :table="r.table" :highlight-rows="r.table.rows.slice(0,20).map((_,n)=>n)" tone="keep" :title="`结果 ${i+1} · ${r.affected} 行受影响`"/></div></template></div></template>
